create or replace function public.admin_catalog_integrity(p_token text) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_admin public."AdminUser"%rowtype; begin
 v_admin:=public._admin_session_user(p_token);
 if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if;
 return jsonb_build_object('summary',jsonb_build_object('products',(select count(*)::int from public."Product"),'published',(select count(*)::int from public."Product" where "isPublished"),'missingBrand',(select count(*)::int from public."Product" where "isPublished" and "brandId" is null),'missingTaxonomy',(select count(*)::int from public."Product" p where p."isPublished" and not exists(select 1 from public."ProductTaxonomy" x where x."productId"=p.id)),'missingImages',(select count(*)::int from public."Product" p where p."isPublished" and not exists(select 1 from public."Media" m where m."productId"=p.id)),'missingTranslations',(select count(*)::int from public."Product" where "isPublished" and (trim(coalesce("nameFa",''))='' or trim(coalesce("nameTr",''))='' or trim(coalesce("nameEn",''))='' or trim(coalesce("nameAr",''))='')),'outOfStock',(select count(*)::int from public."Product" where "isPublished" and stock<=0),'duplicateSku',(select count(*)::int from (select lower(sku) from public."Product" group by lower(sku) having count(*)>1) d)),'issues',coalesce((select jsonb_agg(to_jsonb(x) order by x."updatedAt" desc) from (select p.id,p.sku,p."nameFa",p."nameTr",p."nameEn",p."nameAr",p."isPublished",p.stock,p."updatedAt",array_remove(array[case when p."brandId" is null then 'MISSING_BRAND' end,case when not exists(select 1 from public."ProductTaxonomy" pt where pt."productId"=p.id) then 'MISSING_TAXONOMY' end,case when not exists(select 1 from public."Media" m where m."productId"=p.id) then 'MISSING_IMAGE' end,case when trim(coalesce(p."nameFa",''))='' or trim(coalesce(p."nameTr",''))='' or trim(coalesce(p."nameEn",''))='' or trim(coalesce(p."nameAr",''))='' then 'MISSING_TRANSLATION' end,case when p.stock<=0 then 'OUT_OF_STOCK' end],null)::text[] as issues from public."Product" p where p."isPublished" and (p."brandId" is null or not exists(select 1 from public."ProductTaxonomy" pt where pt."productId"=p.id) or not exists(select 1 from public."Media" m where m."productId"=p.id) or trim(coalesce(p."nameFa",''))='' or trim(coalesce(p."nameTr",''))='' or trim(coalesce(p."nameEn",''))='' or trim(coalesce(p."nameAr",''))='' or p.stock<=0) limit 300) x),'[]'::jsonb));
end $$;
create or replace function public.admin_booking_detail(p_token text,p_id text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_row jsonb; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'SALES'::"AdminRole",'SUPPORT'::"AdminRole") then raise exception 'forbidden'; end if; select to_jsonb(b) into v_row from public."ServiceBooking" b where b.id=p_id; return v_row; end $$;
create or replace function public.admin_catalog_export(p_token text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; return coalesce((select jsonb_agg(to_jsonb(x) order by x.sku) from (select p.id,p.sku,p.slug,p."nameFa",p."nameTr",p."nameEn",p."nameAr",p.price,p.stock,p."isPublished",p."isFeatured",p."isNewArrival",c.slug as "primaryCategorySlug",coalesce(b.name,p.brand,'') as brand,coalesce((select string_agg(c2.slug,';' order by c2.slug) from public."ProductSecondaryCategory" pc join public."Category" c2 on c2.id=pc."categoryId" where pc."productId"=p.id),'') as "secondaryCategories",coalesce((select string_agg(t.type||':'||t.slug,';' order by t.type,t.slug) from public."ProductTaxonomy" pt join public."TaxonomyTerm" t on t.id=pt."termId" where pt."productId"=p.id),'') as taxonomy from public."Product" p join public."Category" c on c.id=p."categoryId" left join public."Brand" b on b.id=p."brandId") x),'[]'::jsonb); end $$;